// ============================================================
// WF4 — ROUTER: Detect Step A or Step B
// Step A = { action: 'get_slots', provider_id, booking_date, availability_slots }
// Step B = { action: 'confirm', provider_id, slot, booking_date, ... }
// ============================================================
const body = $input.first().json.body;
const action = body.action || 'get_slots';
console.log('=== WF4 Router ===');
console.log('Action:', action);
console.log('Body:', JSON.stringify(body));
return [{ json: { ...body, action } }];

// ============================================================
// WF4 STEP A — Build Available Slot List with Travel-Time Buffer
// ============================================================
const requestData = $('Detect Step A or Step B').first().json;
const supabaseRows = $input.all();

// ── Service duration map (minutes) ───────────────────────────
// Covers the actual job time + 30-min travel/cleanup buffer
const SERVICE_DURATIONS = {
  'ac repair':              120,
  'ac installation':        180,
  'ac gas refill':           90,
  'plumber':                 90,
  'electrician':            120,
  'carpenter':              180,
  'painter':                240,
  'tutor':                   60,
  'beautician':             120,
  'generator mechanic':     120,
  'fridge repair':          120,
  'washing machine repair': 120,
  'geyser repair':           90,
  'solar installation':     300,
  'pest control':           120,
  'deep cleaning':          240,
  'default':                 90
};

const TRAVEL_BUFFER_MINS = 30;

// Look up duration for this service type
const serviceKey = (requestData.service_type || '').toLowerCase();
const matchedKey = Object.keys(SERVICE_DURATIONS).find(k => serviceKey.includes(k));
const jobDurationMins = SERVICE_DURATIONS[matchedKey] || SERVICE_DURATIONS['default'];
const totalBlockMins = jobDurationMins + TRAVEL_BUFFER_MINS;

// ── Parse slot string → minutes since midnight ────────────────
function slotToMins(slotStr) {
  if (!slotStr) return null;
  // Handle "11:00 AM" / "2:00 PM" / "14:00" formats
  const upper = slotStr.toUpperCase().trim();
  const isPM = upper.includes('PM');
  const isAM = upper.includes('AM');
  const clean = upper.replace('AM', '').replace('PM', '').trim();
  const [hStr, mStr] = clean.split(':');
  let h = parseInt(hStr);
  const m = parseInt(mStr) || 0;
  if (isPM && h !== 12) h += 12;
  if (isAM && h === 12) h = 0;
  return h * 60 + m;
}

function formatSlotLabel(time) {
  const [h, m] = time.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const hour = h > 12 ? h - 12 : h === 0 ? 12 : h;
  return `${hour}:${String(m).padStart(2, '0')} ${period}`;
}

// ── Get booked slots from Supabase ────────────────────────────
const bookedInDb = supabaseRows
  .map(row => row.json?.slot)
  .filter(Boolean);

const bookedMins = bookedInDb.map(s => slotToMins(s)).filter(v => v !== null);

// ── All possible slots for this provider ──────────────────────
const allSlots = requestData.availability_slots ||
  ['09:00', '10:00', '11:00', '12:00', '14:00', '15:00', '16:00', '17:00'];

// ── Seed-based randomisation (simulates offline bookings) ─────
const seed = requestData.place_id || requestData.provider_id || 'default_seed';

const slotList = allSlots.map((slot, index) => {
  const slotMins = slotToMins(slot);

  // Is this slot already directly booked in DB?
  const directlyBooked = bookedInDb.includes(slot);

  // Does this slot fall inside the buffer window of ANY booked slot?
  // i.e. a booked slot at T blocks slots from T to T+totalBlockMins
  const blockedByBuffer = bookedMins.some(bookedStart => {
    return slotMins > bookedStart && slotMins < bookedStart + totalBlockMins;
  });

  // Also block if THIS slot being booked would overlap a later booked slot
  // i.e. if booking at slotMins would still be running when bookedStart begins
  const wouldOverlapNext = bookedMins.some(bookedStart => {
    return slotMins < bookedStart && slotMins + totalBlockMins > bookedStart;
  });

  // Seed-based pseudo-random offline bookings (~20% of slots)
  const isRandomlyBusy = (seed.charCodeAt(index % seed.length) % 5) === 0;

  const isAvailable = !directlyBooked && !blockedByBuffer && !wouldOverlapNext && !isRandomlyBusy;

  return {
    time: slot,
    label: formatSlotLabel(slot),
    available: isAvailable,
    blocked_reason: directlyBooked ? 'booked'
      : blockedByBuffer ? `within ${totalBlockMins}min buffer of earlier booking`
      : wouldOverlapNext ? `would overlap next booking`
      : isRandomlyBusy ? 'offline'
      : null
  };
});

const freeSlots = slotList.filter(s => s.available);

return [{ json: {
  status: 'slots_ready',
  action: 'get_slots',
  provider_id: requestData.place_id || requestData.provider_id,
  provider_name: requestData.provider_name,
  service_type: requestData.service_type,
  location: requestData.location,
  price_pkr: parseInt(requestData.price_pkr) || 0,
  booking_date: requestData.booking_date,
  availability_slots: allSlots,
  slots: slotList,
  free_count: freeSlots.length,
  booked_count: bookedInDb.length,
  job_duration_mins: jobDurationMins,
  travel_buffer_mins: TRAVEL_BUFFER_MINS,
  total_block_mins: totalBlockMins,
  message: freeSlots.length === 0
    ? 'Koi slot available nahi hai is date pe.'
    : `${freeSlots.length} slot(s) available — slot chunein`,
  workflow: 'WF4-StepA'
}}];

// ============================================================
// WF4 STEP B — Validate Confirm Request with Buffer Check
// ============================================================
const body = $input.first().json;

const required = [
  'provider_id', 'provider_name',
  'service_type', 'location',
  'price_pkr', 'slot', 'booking_date'
];

const effectiveProviderId = body.provider_id || body.place_id;
const missing = required.filter(f => f === 'provider_id' ? !effectiveProviderId : !body[f]);

if (missing.length > 0) {
  return [{ json: {
    status: 'validation_error',
    message: `Missing fields: ${missing.join(', ')}`,
    received: body
  }}];
}

// ── Same duration map as Step A ───────────────────────────────
const SERVICE_DURATIONS = {
  'ac repair':              120,
  'ac installation':        180,
  'ac gas refill':           90,
  'plumber':                 90,
  'electrician':            120,
  'carpenter':              180,
  'painter':                240,
  'tutor':                   60,
  'beautician':             120,
  'generator mechanic':     120,
  'fridge repair':          120,
  'washing machine repair': 120,
  'geyser repair':           90,
  'solar installation':     300,
  'pest control':           120,
  'deep cleaning':          240,
  'default':                 90
};

const TRAVEL_BUFFER_MINS = 30;

function slotToMins(slotStr) {
  if (!slotStr) return null;
  const upper = slotStr.toUpperCase().trim();
  const isPM = upper.includes('PM');
  const isAM = upper.includes('AM');
  const clean = upper.replace('AM', '').replace('PM', '').trim();
  const [hStr, mStr] = clean.split(':');
  let h = parseInt(hStr);
  const m = parseInt(mStr) || 0;
  if (isPM && h !== 12) h += 12;
  if (isAM && h === 12) h = 0;
  return h * 60 + m;
}

const serviceKey = (body.service_type || '').toLowerCase();
const matchedKey = Object.keys(SERVICE_DURATIONS).find(k => serviceKey.includes(k));
const jobDurationMins = SERVICE_DURATIONS[matchedKey] || SERVICE_DURATIONS['default'];
const totalBlockMins = jobDurationMins + TRAVEL_BUFFER_MINS;

const timestamp = Date.now();
const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
const bookingId = `BK-${new Date().getFullYear()}-${timestamp}-${random}`;

console.log('=== WF4 Step B — Confirming Booking ===');
console.log('Booking ID:', bookingId);
console.log('Provider ID:', effectiveProviderId);
console.log('Slot:', body.slot, 'on', body.booking_date);
console.log('Job duration:', jobDurationMins, 'mins + buffer:', TRAVEL_BUFFER_MINS, 'mins');

return [{ json: {
  ...body,
  provider_id: effectiveProviderId,
  price_pkr: parseInt(body.price_pkr) || 0,
  booking_id: bookingId,
  user_name: body.user_name || 'Guest User',
  job_duration_mins: jobDurationMins,
  travel_buffer_mins: TRAVEL_BUFFER_MINS,
  total_block_mins: totalBlockMins,
  requested_slot_mins: slotToMins(body.slot)
}}];

// ============================================================
// WF4 STEP B — Check if slot was grabbed by someone else
// Now also checks travel-time buffer conflicts
// ============================================================
const bookingData = $('Step B — Validate Confirm Request').first().json;
const supabaseRows = $input.all();

// ── Parse slot string → minutes since midnight ────────────────
function slotToMins(slotStr) {
  if (!slotStr) return null;
  const upper = slotStr.toUpperCase().trim();
  const isPM = upper.includes('PM');
  const isAM = upper.includes('AM');
  const clean = upper.replace('AM', '').replace('PM', '').trim();
  const [hStr, mStr] = clean.split(':');
  let h = parseInt(hStr);
  const m = parseInt(mStr) || 0;
  if (isPM && h !== 12) h += 12;
  if (isAM && h === 12) h = 0;
  return h * 60 + m;
}

// Check for exact slot match (race condition)
const exactSlotTaken = supabaseRows.some(row => row.json && row.json.booking_id);

// Check for buffer conflict against any confirmed bookings returned
const requestedMins = bookingData.requested_slot_mins
  || slotToMins(bookingData.slot);
const totalBlockMins = bookingData.total_block_mins || 120;

const bufferConflict = supabaseRows.some(row => {
  if (!row.json?.slot) return false;
  const existingMins = slotToMins(row.json.slot);
  if (existingMins === null) return false;
  // Existing booking blocks our slot
  const existingBlocks = requestedMins > existingMins
    && requestedMins < existingMins + totalBlockMins;
  // Our booking would still be running when existing starts
  const weBlockExisting = requestedMins < existingMins
    && requestedMins + totalBlockMins > existingMins;
  return existingBlocks || weBlockExisting;
});

const slotTaken = exactSlotTaken || bufferConflict;

console.log('Race condition check:');
console.log('  Exact slot taken:', exactSlotTaken);
console.log('  Buffer conflict:', bufferConflict);
console.log('  Requested slot:', bookingData.slot, '(' + requestedMins + ' mins)');
console.log('  Block window:', totalBlockMins, 'mins');

if (slotTaken) {
  const reason = bufferConflict
    ? `Slot conflicts with an existing booking's service window (${totalBlockMins} min block)`
    : 'Slot was just booked by another user';

  console.log('CONFLICT:', reason);
  return [{ json: {
    status: 'slot_taken',
    slot_requested: bookingData.slot,
    provider_name: bookingData.provider_name,
    booking_date: bookingData.booking_date,
    conflict_reason: reason,
    message: 'Yeh slot abhi kisi aur ne book kar liya. Kripya doosra slot chunein.',
    trigger_reslot: true,
    provider_id: bookingData.provider_id,
    availability_slots: bookingData.availability_slots
  }}];
}

return [{ json: { ...bookingData, slot_status: 'free' } }];

// ============================================================
// WF4 STEP B — Generate Confirmation Receipt
// ============================================================

const bookingData = $('Step B — Is Slot Still Free?').first().json;

function formatSlotLabel(time) {
  const [h, m] = time.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  const hour = h > 12 ? h - 12 : h === 0 ? 12 : h;
  return `${hour}:${String(m).padStart(2, '0')} ${period}`;
}

const receipt = {
  booking_id: bookingData.booking_id,
  status: 'confirmed',
  service: bookingData.service_type,
  provider: {
    id: bookingData.provider_id,
    name: bookingData.provider_name
  },
  appointment: {
    date: bookingData.booking_date,
    time: bookingData.slot,
    time_label: formatSlotLabel(bookingData.slot),
    location: bookingData.location
  },
  payment: {
    estimated_pkr: bookingData.price_pkr,
    method: 'Cash on service',
    note: 'Final price may vary based on actual work done'
  },
  customer: {
    name: bookingData.user_name,
    email: bookingData.user_email  // Include user_email here
  },
  confirmation_lines: [
    `✅ Booking confirmed!`,
    `🎫 ID: ${bookingData.booking_id}`,
    `📅 ${bookingData.booking_date} at ${formatSlotLabel(bookingData.slot)}`,
    `👷 ${bookingData.provider_name}`,
    `📍 ${bookingData.location}`,
    `💰 PKR ${bookingData.price_pkr}`,
    `📱 Provider will call 30 min before arrival`,
    `📧 Email: ${bookingData.user_email}`  // Optional, include in confirmation lines if needed
  ],
  simulated_whatsapp:
    `Assalam o Alaikum! Aapki booking confirm ho gayi.\n` +
    `🎫 ID: ${bookingData.booking_id}\n` +
    `🔧 Service: ${bookingData.service_type}\n` +
    `👷 Provider: ${bookingData.provider_name}\n` +
    `📅 ${bookingData.booking_date} at ${formatSlotLabel(bookingData.slot)}\n` +
    `💰 PKR ${bookingData.price_pkr} (cash on delivery)\n` +
    `📧 Email: ${bookingData.user_email}\n` +  // Optional, include in WhatsApp text if needed
    `Shukriya! — Khadmat AI`,
  next_steps: [
    'Provider will call you 1 hour before arrival',
    'Keep your phone available',
    'Pay in cash after service is done'
  ],
  workflow: 'WF4-StepB',
  created_at: new Date().toISOString()
};

console.log('=== Booking Confirmed ===');
console.log('ID:', receipt.booking_id);
return [{ json: receipt }];

// ============================================================
// WF4 STEP B — Slot Taken Fallback
// Triggered when race condition detected
// ============================================================
const data = $input.first().json;

console.log('=== Slot Taken Fallback ===');
console.log('Slot:', data.slot_requested);

const alternatives = [1, 2, 3].map(daysAhead => {
  const d = new Date();
  d.setDate(d.getDate() + daysAhead);
  const dateStr =
    d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
  return {
    date: dateStr,
    label: daysAhead === 1 ? 'Kal (Tomorrow)'
         : daysAhead === 2 ? 'Parson'
         : '3 din baad',
    slots: ['09:00', '10:00', '14:00']
  };
});

return [{ json: {
  status: 'slot_taken',
  message: data.message,
  slot_requested: data.slot_requested,
  provider_name: data.provider_name,
  booking_date: data.booking_date,
  action_required: 'get_slots',
  hint: 'Call get_slots again to see updated availability',
  alternative_dates: alternatives,
  waitlist: {
    available: true,
    message: 'Waitlist mein add kar dein? Slot khali hone par inform kar denge.'
  },
  workflow: 'WF4-SlotTakenFallback',
  timestamp: new Date().toISOString()
}}];
